const normalizeLookup = (value) => String(value ?? "").trim().replace(/^lucide(?::|\/)/i, "").replace(/([a-z])([A-Z])/g, "$1-$2").replace(/[\s_]+/g, "-").toLowerCase();
export function resolveIcon(name) {
  const requestedAlias = String(name ?? "").trim();
  const exact = iconDefinitions[requestedAlias];
  if (exact) return { ...exact, resolvedAlias: requestedAlias, resolution: "canonical", requestedAlias };
  const normalized = normalizeLookup(requestedAlias);
  const flatAlias = flatAliasAliases[normalized];
  if (flatAlias && iconDefinitions[flatAlias]) return { ...iconDefinitions[flatAlias], resolvedAlias: flatAlias, resolution: "flat-alias", requestedAlias };
  const compatibilityAlias = compatibilityAliases[normalized];
  if (compatibilityAlias && iconDefinitions[compatibilityAlias]) return { ...iconDefinitions[compatibilityAlias], resolvedAlias: compatibilityAlias, resolution: "compatibility-alias", requestedAlias };
  const sourceAlias = sourceNameAliases[normalized];
  if (sourceAlias && iconDefinitions[sourceAlias]) return { ...iconDefinitions[sourceAlias], resolvedAlias: sourceAlias, resolution: "source-name", requestedAlias };
  const suffixAlias = semanticSuffixAliases[normalized.split("/").at(-1)];
  if (suffixAlias && iconDefinitions[suffixAlias]) return { ...iconDefinitions[suffixAlias], resolvedAlias: suffixAlias, resolution: "semantic-suffix", requestedAlias };
  return { ...unresolvedIconDefinition, resolvedAlias: null, resolution: "unresolved-fallback", requestedAlias };
}
export function iconMarkup(name, { size = 20, decorative = true, ariaLabel = "", iconStyle = "regular" } = {}) {
  if (!["regular", "solid"].includes(iconStyle)) throw new Error(`Unsupported icon style: ${iconStyle}`);
  if (![16, 20, 24].includes(Number(size))) throw new Error(`Unsupported icon display size: ${size}`);
  const definition = resolveIcon(name);
  const label = decorative ? " aria-hidden=\"true\"" : ` role=\"img\" aria-label=\"${String(ariaLabel).replaceAll("\"", "&quot;")}\"`;
  return `<svg class=\"tui-icon tui-icon--${iconStyle}\" viewBox=\"${definition.viewBox}\" width=\"${size}\" height=\"${size}\" data-icon-alias=\"${name}\" data-icon-size=\"${size}\" data-display-size-token=\"size/${size}\" data-icon-kind=\"${iconStyle}\" data-icon-source=\"${definition.source}\"${label}>${definition.content}</svg>`;
}
